from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.linear_model import LogisticRegression
from scipy.sparse import hstack


# These must match the columns generated by
# src/proxy_features.py
PROXY_COLUMNS = [
    "repeated_char_count",
    "max_elongation",
    "elongation_ratio",
    "exclamation_count",
    "question_count",
    "period_count",
    "ellipsis_count",
    "punctuation_stack_count",
    "repeated_punctuation_ratio",
    "uppercase_ratio",
    "emoji_count",
    "has_emoji",
    "final_particle_count",
    "has_final_particle",
    "interjection_count",
    "has_interjection",
    "text_length",
    "token_count",
    "exclamation_question_count",
    "emoji_punctuation_interaction",
    "elongation_punctuation_interaction",
]


def build_proxy_model():

    vectorizer = TfidfVectorizer(
        ngram_range=(1, 2),
        sublinear_tf=True,
        min_df=2,
        max_features=10000
    )

    classifier = LogisticRegression(
        max_iter=2000,
        class_weight="balanced",
        random_state=42
    )

    return vectorizer, classifier


def combine_features(text_matrix, proxy_matrix):

    return hstack(
        [
            text_matrix,
            proxy_matrix
        ],
        format="csr"
    )